<?php

declare(strict_types=1);

namespace VeryCodeCom\FurgonetkaApi\Enum;

/**
 * Who provides the customs documents (`duty.documents_owner`).
 *
 * Read with `tryFrom()`: Furgonetka adds values without notice, and a value this release does not
 * know reads as null while the response DTO keeps the raw string next to it.
 */
enum DutyDocumentsOwner: string
{
    /** The documents are generated by Furgonetka. */
    case Provided = 'provided';

    /** The sender uploads his own documents and lists their UUIDs in `duty.documents_uuids`; FedEx and UPS only. */
    case Client = 'client';
}
